package org.humanjourney.core.npc.economy;
import com.google.gson.*;
import java.util.*;
import org.humanjourney.core.npc.context.*;
import static org.humanjourney.core.npc.economy.JsonData.*;
public record EconomyCatalog(Map<String,Commodity> commodities,Map<String,Family> families){
 public record Source(String id,String json){}
 @FunctionalInterface public interface Items{int maximum(String id,JsonObject components);}
 public record Rule(int priority,Map<String,String> context,String item){public Rule{context=Map.copyOf(context);}boolean matches(NpcContext c){return context.entrySet().stream().allMatch(e->e.getValue().equals(switch(e.getKey()){case "era"->c.era();case "macro_region"->c.macroRegion();case "local_area"->c.localArea();case "season"->c.season();default->"";}));}}
 public record Family(String id,List<String> members,String defaultMember,List<Rule> outputs){public Family{members=List.copyOf(members);outputs=List.copyOf(outputs);}public String resolve(NpcContext context,String override){if(override!=null){if(!members.contains(override))throw new IllegalArgumentException("family override is not a member: "+id);return override;}var matches=outputs.stream().filter(r->r.matches(context)).sorted(Comparator.comparingInt(Rule::priority).reversed()).toList();if(matches.size()>1&&matches.get(0).priority()==matches.get(1).priority())throw new IllegalArgumentException("ambiguous family output rules: "+id);return matches.isEmpty()?defaultMember:matches.getFirst().item();}}
 public record Commodity(String id,String era,long value,String rarity,int maxUses,List<String> sellers,List<String> buyers,String item,String family,GeoProfile.Availability availability,JsonObject components){public Commodity{sellers=List.copyOf(sellers);buyers=List.copyOf(buyers);components=components.deepCopy();}@Override public JsonObject components(){return components.deepCopy();}}
 public EconomyCatalog{commodities=Map.copyOf(commodities);families=Map.copyOf(families);}
 public static EconomyCatalog empty(){return new EconomyCatalog(Map.of(),Map.of());}
 public static EconomyCatalog parse(List<Source> goods,List<Source> familyFiles,Set<String> eras,Map<String,NpcArchetype> roles,NpcGeography geo,Map<String,Set<String>> vocabulary,Items items){
  var families=new TreeMap<String,Family>();for(var source:familyFiles){try{var o=object(JsonParser.parseString(source.json()));keys(o,"schema_version","id","members","default_member","output_overrides");schema(o);id(source.id());if(o.has("id")&&!text(o,"id").equals(source.id()))throw new IllegalArgumentException("family ID/path mismatch");var members=strings(o.get("members"));if(members.isEmpty()||members.size()>256)throw new IllegalArgumentException("family needs 1..256 members");for(String member:members)checkItem(member,new JsonObject(),items);String defaultMember=o.has("default_member")?text(o,"default_member"):members.getFirst();if(!members.contains(defaultMember))throw new IllegalArgumentException("invalid default_member");List<Rule> rules=new ArrayList<>();if(o.has("output_overrides")){if(!o.get("output_overrides").isJsonArray())throw new IllegalArgumentException("output_overrides must be array");for(var e:o.getAsJsonArray("output_overrides")){var rule=object(e);keys(rule,"priority","when","item");var when=object(rule.get("when"));keys(when,"era","macro_region","local_area","season");var conditions=new TreeMap<String,String>();for(String key:when.keySet()){String value=text(when,key);boolean valid=switch(key){case "era"->eras.contains(value);case "macro_region"->geo.macros().stream().anyMatch(a->a.id().equals(value));case "local_area"->geo.locals().stream().anyMatch(a->a.id().equals(value));case "season"->NpcArchetype.SEASONS.contains(value);default->false;};if(!valid)throw new IllegalArgumentException("unknown family context "+key+": "+value);conditions.put(key,value);}String item=text(rule,"item");if(!members.contains(item))throw new IllegalArgumentException("family rule item is not a member");rules.add(new Rule(rule.has("priority")?integer(rule,"priority",-1000000,1000000):0,conditions,item));}}for(int i=0;i<rules.size();i++)for(int j=i+1;j<rules.size();j++){var a=rules.get(i);var b=rules.get(j);if(a.priority()!=b.priority())continue;boolean overlap=true;for(String key:a.context().keySet())if(b.context().containsKey(key)&&!a.context().get(key).equals(b.context().get(key)))overlap=false;if(overlap)throw new IllegalArgumentException("same-priority family output conditions overlap; assign distinct priorities");}if(families.put(source.id(),new Family(source.id(),members,defaultMember,rules))!=null)throw new IllegalArgumentException("duplicate family");}catch(Exception e){throw new IllegalArgumentException(source.id()+": "+e.getMessage(),e);}}
  var commodities=new TreeMap<String,Commodity>();for(var source:goods){try{var o=object(JsonParser.parseString(source.json()));keys(o,"schema_version","id","era","value","rarity","maxUses","sellers","buyers","item","family","sellAvailability","components");schema(o);id(source.id());if(o.has("id")&&!text(o,"id").equals(source.id()))throw new IllegalArgumentException("commodity ID/path mismatch");String era=text(o,"era");if(!eras.contains(era))throw new IllegalArgumentException("unknown Era: "+era);var v=o.get("value");if(v==null||!v.isJsonPrimitive()||!v.getAsJsonPrimitive().isNumber())throw new IllegalArgumentException("value must be numeric");long value=v.getAsBigDecimal().setScale(6,java.math.RoundingMode.UNNECESSARY).movePointRight(6).longValueExact();if(value<=0||value>1_000_000_000_000_000L)throw new IllegalArgumentException("value must be >0 and <=1000000000, at most 6 decimal places");var sellers=roles(o,"sellers",roles,era);var buyers=roles(o,"buyers",roles,era);if(sellers.isEmpty()&&buyers.isEmpty())throw new IllegalArgumentException("commodity needs a seller or buyer");if(o.has("item")==o.has("family"))throw new IllegalArgumentException("exactly one of item/family required");String item=o.has("item")?text(o,"item"):null,family=o.has("family")?qualify(text(o,"family")):null;if(family!=null&&!families.containsKey(family))throw new IllegalArgumentException("unknown family: "+family);var components=o.has("components")?object(o.get("components")):new JsonObject();for(String member:item==null?families.get(family).members():List.of(item)){checkItem(member,new JsonObject(),items);checkItem(member,components,items);}var commodity=new Commodity(source.id(),era,value,text(o,"rarity"),integer(o,"maxUses",1,1000000),sellers,buyers,item,family,GeoProfile.availability(o.get("sellAvailability"),vocabulary),components);if(commodities.put(source.id(),commodity)!=null)throw new IllegalArgumentException("duplicate commodity");}catch(Exception e){throw new IllegalArgumentException(source.id()+": "+e.getMessage(),e);}}
  return new EconomyCatalog(commodities,families);
 }
 private static List<String> roles(JsonObject o,String key,Map<String,NpcArchetype> roles,String era){List<String> out=new ArrayList<>();for(String id:strings(o.get(key))){String role=qualify(id);if(!roles.containsKey(role)||!roles.get(role).eras().contains(era))throw new IllegalArgumentException("unknown/unavailable "+era+" role: "+role);if(out.contains(role))throw new IllegalArgumentException("duplicate role: "+role);out.add(role);}return out;}
 private static void checkItem(String item,JsonObject components,Items items){id(item);int max=items.maximum(item,components.deepCopy());if(item.equals("minecraft:air")||max<1||max>99)throw new IllegalArgumentException("invalid Minecraft item/stack components: "+item);}
 public List<String> members(Commodity c){return c.item()!=null?List.of(c.item()):families.get(c.family()).members();}
 public String output(Commodity c,NpcContext context,EconomySettings settings){return c.item()!=null?c.item():families.get(c.family()).resolve(context,settings.familyOutputs().get(c.family()));}
 public int inputMaximum(Commodity c,Items items){return members(c).stream().mapToInt(id->items.maximum(id,new JsonObject())).min().orElseThrow();}
 public void validateSettings(EconomySettings settings,NpcContext context){for(var e:settings.familyOutputs().entrySet()){if(!families.containsKey(e.getKey()))throw new IllegalArgumentException("unknown family override: "+e.getKey());families.get(e.getKey()).resolve(context,e.getValue());}for(var f:families.values())f.resolve(context,null);}
}
